Part.Source:
Event Start
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Grid_Group.GridInternalName = Grid.InternalName
Grid.Rows = Page.Rows Grid_Empowerer.GridInternalName = Grid.InternalName
If &HTTPRequest.Method = HttpMethod.Get Do 'LoadSavedFilters' EndIf &GAMSession = GAMSession.Get(&GAMErrors) DDO_Grid.GridInternalName = Grid.InternalName DDO_Grid.GAMOAuthToken = &GAMSession.Token Form.Caption = 'Diagnóstico Nutricional'
Do 'PrepareTransaction' Do 'LoadGridState' &DDO_TitleSettingsIcons = GetWWPTitleSettingsIcons() GridPaginationBar.RowsPerPageSelectedValue = Grid.Rows
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
do 'CarregaGraficos'
EndEvent
Event Refresh
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
LoadWWPContext.Call(&WWPContext)
Do Case Case &ManageFiltersExecutionStep = 1 &ManageFiltersExecutionStep = 2 Case &ManageFiltersExecutionStep = 2 &ManageFiltersExecutionStep = 0 Do 'LoadSavedFilters' EndCase Do 'SaveGridState'
&GridCurrentPage = Grid.CurrentPage &GridPageCount = Grid.PageCount &GridAppliedFilters = WWP_GetAppliedFiltersDescription(&Pgmname) &Grid_GroupCaption.SetEmpty()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event GridPaginationBar.ChangePage
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Do Case Case GridPaginationBar.SelectedPage = !'Previous' Grid.PreviousPage() Case GridPaginationBar.SelectedPage = !'Next' Grid.NextPage() Otherwise &PageToGo.FromString(GridPaginationBar.SelectedPage) Grid.GotoPage(&PageToGo) EndCase
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event GridPaginationBar.ChangeRowsPerPage
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Grid.Rows = GridPaginationBar.RowsPerPageSelectedValue Grid.FirstPage()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event DDO_Grid.OnOptionClicked
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Do Case Case DDO_Grid.ActiveEventKey = !'<#OrderASC#>' OR DDO_Grid.ActiveEventKey = !'<#OrderDSC#>' &OrderedDsc = iif(DDO_Grid.ActiveEventKey = !'<#OrderDSC#>', true, false) Do 'SetDDOSortedStatus' Grid.FirstPage() Case DDO_Grid.ActiveEventKey = !'<#Filter#>' Do Case Case DDO_Grid.SelectedColumn = !'diag_nutricional_AlunoNome' &TFdiag_nutricional_AlunoNome = DDO_Grid.FilteredText_get &TFdiag_nutricional_AlunoNome_Sel = DDO_Grid.SelectedValue_get EndCase Grid.FirstPage() EndCase
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event Grid.Load
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Grid_GroupCaption = diag_nutricional_NomeEscola &Grid_GroupCaption = format('%1: %2', "Escola", iif(diag_nutricional_NomeEscola.IsEmpty(), 'WWP_FilterEmpty', &Grid_GroupCaption))
&Sexo = iif(diag_nutricional_Sexo = 1, 'Masculino', 'Feminino')
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event ddo_ManageFilters.OnOptionClicked
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Do Case Case ddo_ManageFilters.ActiveEventKey = !'<#Clean#>' Do 'CleanFilters' Grid.FirstPage() Case ddo_ManageFilters.ActiveEventKey = !'<#Save#>' Do 'SaveGridState' SaveFilterAs.Popup(!'DiagnosticoNutricionalFilters', &PgmName + !"GridState") &ManageFiltersExecutionStep = 2 Refresh Case ddo_ManageFilters.ActiveEventKey = !'<#Manage#>' ManageFilters.Popup(!'DiagnosticoNutricionalFilters') &ManageFiltersExecutionStep = 2 Refresh Otherwise &ManageFiltersXml = GetFilterByName(!'DiagnosticoNutricionalFilters', ddo_ManageFilters.ActiveEventKey) If &ManageFiltersXml.IsEmpty() msg('WWP_FilterNotExist') Else Do 'CleanFilters' SaveGridState.Call(&PgmName + !"GridState", &ManageFiltersXml) &GridState.FromXml(&ManageFiltersXml) &OrderedDsc = &GridState.OrderedDsc Do 'SetDDOSortedStatus' Do 'LoadRegFiltersState' Grid.FirstPage() EndIf EndCase
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Sub 'SetDDOSortedStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
DDO_Grid.SortedStatus = !'-1:' + iif(&OrderedDsc, !'DSC', !'ASC')
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadSavedFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ManageFiltersData = WWP_ManageFiltersLoadSavedFilters(!'DiagnosticoNutricionalFilters', '', '', False)
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CleanFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&diag_nutricional_Ano.SetEmpty() &diag_nutricional_Escola.SetEmpty() &diag_nutricional_NumColeta.SetEmpty() &TFdiag_nutricional_AlunoNome.SetEmpty() &TFdiag_nutricional_AlunoNome_Sel.SetEmpty() DDO_Grid.SelectedValue_set = '' DDO_Grid.FilteredText_set = ''
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(&PgmName + !"GridState") = !"" &GridState.FromXml(LoadGridState.Udp(&PgmName + !"GridState")) Else &GridState.FromXml(&Session.Get(&PgmName + !"GridState")) Endif &OrderedDsc = &GridState.OrderedDsc Do 'SetDDOSortedStatus' Do 'LoadRegFiltersState' If not &GridState.PageSize.Trim().IsEmpty() Grid.Rows = &GridState.PageSize.ToNumeric() EndIf Grid.CurrentPage = &GridState.CurrentPage
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadRegFiltersState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"DIAG_NUTRICIONAL_ANO" &diag_nutricional_Ano.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"DIAG_NUTRICIONAL_ESCOLA" &diag_nutricional_Escola.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"DIAG_NUTRICIONAL_NUMCOLETA" &diag_nutricional_NumColeta.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDIAG_NUTRICIONAL_ALUNONOME" &TFdiag_nutricional_AlunoNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDIAG_NUTRICIONAL_ALUNONOME_SEL" &TFdiag_nutricional_AlunoNome_Sel.FromString(&GridStateFilterValue.Value) EndCase EndFor DDO_Grid.SelectedValue_set = WWP_GetFilterVal(&TFdiag_nutricional_AlunoNome_Sel.IsEmpty(), &TFdiag_nutricional_AlunoNome_Sel) DDO_Grid.FilteredText_set = WWP_GetFilterVal(&TFdiag_nutricional_AlunoNome.IsEmpty(), &TFdiag_nutricional_AlunoNome)
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'SaveGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&GridState.FromXml(&Session.Get(&PgmName + !"GridState"))
// Save grid state in session. &GridState.OrderedDsc = &OrderedDsc &GridState.FilterValues.Clear() WWP_GridStateAddFilterValue(&GridState, !"DIAG_NUTRICIONAL_ANO", "Ano", not &diag_nutricional_Ano.IsEmpty(), 0, &diag_nutricional_Ano.ToString().Trim(), trim(&diag_nutricional_Ano.ToFormattedString()), False, '', '') WWP_GridStateAddFilterValue(&GridState, !"DIAG_NUTRICIONAL_ESCOLA", "Escola", not &diag_nutricional_Escola.IsEmpty(), 0, &diag_nutricional_Escola.ToString().Trim(), trim(&diag_nutricional_Escola.ToFormattedString()), False, '', '') WWP_GridStateAddFilterValue(&GridState, !"DIAG_NUTRICIONAL_NUMCOLETA", "Nro Coleta", not &diag_nutricional_NumColeta.IsEmpty(), 0, &diag_nutricional_NumColeta.ToString().Trim(), trim(&diag_nutricional_NumColeta.ToFormattedString()), False, '', '') WWP_GridStateAddFilterValueAndSel(&GridState, !"TFDIAG_NUTRICIONAL_ALUNONOME", "Estudante", not &TFdiag_nutricional_AlunoNome.IsEmpty(), 0, &TFdiag_nutricional_AlunoNome, &TFdiag_nutricional_AlunoNome, False, '', '', not &TFdiag_nutricional_AlunoNome_Sel.IsEmpty(), &TFdiag_nutricional_AlunoNome_Sel, &TFdiag_nutricional_AlunoNome_Sel)
&GridState.PageSize = str(Grid.Rows) &GridState.CurrentPage = Grid.CurrentPage SaveGridState.Call(&PgmName + !"GridState", &GridState.ToXml())
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrepareTransaction'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TrnContext = new() &TrnContext.CallerObject = &Pgmname &TrnContext.CallerOnDelete = True &TrnContext.CallerURL = &HTTPRequest.ScriptName + !"?" + &HTTPRequest.QueryString &TrnContext.TransactionName = !"viewDiagNutricional"
&Session.Set(!"TrnContext", &TrnContext.ToXml())
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Event &diag_nutricional_Ano.ControlValueChanged
do 'CarregaGraficos'
EndEvent
Event &diag_nutricional_Escola.ControlValueChanged
do 'CarregaGraficos'
EndEvent
Event &diag_nutricional_NumColeta.ControlValueChanged
do 'CarregaGraficos'
EndEvent
Sub 'CarregaGraficos'
GraficoTotal.Object = queryDiagnosticoNutricionalIndividual(&diag_nutricional_Ano,&diag_nutricional_Escola,&diag_nutricional_Sexo,&diag_nutricional_NumColeta) GraficoComparativo.Object = queryDiagnosticoNutricionalComparativo(&diag_nutricional_Ano,&diag_nutricional_Escola,&diag_nutricional_NumColeta)
EndSub
